241	            <option value="All">All statuses</option>
242	            {STATUSES.map(s => <option key={s} value={s}>{s}</option>)}
243	          </select>
244	          <select className="logistics-filter" value={filterBay} onChange={(e) => setFilterBay(e.target.value)} aria-label="Filter by bay">
245	            <option value="All">All bays</option>
246	            {BAYS.map(b => <option key={b} value={b}>{b}</option>)}
247	          </select>
248	          <input
249	            type="date"
250	            className="logistics-filter logistics-date"
251	            value={filterDate}
252	            onChange={(e) => setFilterDate(e.target.value)}
253	            aria-label="Filter by slot date"
254	          />
255	          {filterDate && (
256	            <button type="button" className="edit-btn" onClick={() => setFilterDate('')} aria-label="Clear date filter">
257	              Clear date
258	            </button>
259	          )}
