261	
262	        {/* Booking list — plain table styled like Workforce Attendance (no bulky card/heading) */}
263	        <div className="active-bookings">
264	          {loading ? (
265	            <p style={{ padding: '24px', color: '#94a3b8' }}>Loading bookings...</p>
266	          ) : bookings.length === 0 ? (
267	            <p style={{ padding: '24px', color: '#94a3b8' }}>No bookings scheduled yet.</p>
268	          ) : filtered.length === 0 ? (
269	            <p style={{ padding: '24px', color: '#94a3b8' }}>No bookings match your filters.</p>
270	          ) : (
271	            <div className="table-container">
272	              <table className="management-table">
273	                <thead>
274	                  <tr>
275	                    <th>Ref</th><th>Plate</th><th>Company</th><th>Driver</th><th>Bay</th>
276	                    <th>Slot</th><th>Status</th><th>Actions</th>
277	                  </tr>
278	                </thead>
279	                <tbody>
280	                  {filtered.map((b) => {
281	                    const nextStatus = STATUS_FLOW[b.status];
282	                    const isClosed = CLOSED.includes(b.status);
283	                    const canEditOrCancel = !isClosed && (role === 'FM' || role === 'Tenant');
284	                    const hasActions = (canManage && nextStatus) || canEditOrCancel;
285	                    return (
286	                      <tr key={b.id}>
287	                        <td data-label="Ref" className="booking-ref-cell">{b.booking_ref}</td>
288	                        <td data-label="Plate">{b.license_plate}</td>
289	                        <td data-label="Company" className="booking-wrap-cell">{b.transport_company}</td>
290	                        <td data-label="Driver" className="booking-wrap-cell">{b.driver_name || '—'}</td>
291	                        <td data-label="Bay">{b.loading_bay}</td>
292	                        <td data-label="Slot">{fmtSlot(b)}</td>
293	                        <td data-label="Status"><span className={`status-badge ${String(b.status).toLowerCase()}`}>{b.status}</span></td>
294	                        <td data-label="Actions" className="booking-actions-cell">
295	                          {hasActions ? (
296	                            <div className="booking-action-group" aria-label={`Actions for ${b.booking_ref}`}>
297	                              {canManage && nextStatus && (
298	                                <button className="edit-btn booking-action-btn booking-action-primary" onClick={() => updateStatus(b.id, nextStatus)}>
299	                                  Mark {nextStatus}
300	                                </button>
301	                              )}
302	                              {canEditOrCancel && (
303	                                <button className="edit-btn booking-action-btn" onClick={() => openEdit(b)}>
304	                                  Edit
305	                                </button>
306	                              )}
307	                              {canEditOrCancel && (
308	                                <button className="edit-btn booking-action-btn booking-action-danger" onClick={() => cancelBooking(b.id)}>
309	                                  Cancel
310	                                </button>
311	                              )}
312	                            </div>
313	                          ) : (
314	                            <span className="booking-actions-none">—</span>
315	                          )}
316	                        </td>
317	                      </tr>
318	                    );
319	                  })}
320	                </tbody>
321	              </table>
322	            </div>
323	          )}
324	        </div>
325	
326	        {/* Create-booking modal (opens via "+ New Booking") */}
327	        {isFormOpen && canCreate && (
328	          <div className="modal-overlay" onClick={closeForm}>
329	            <div className="modal-content booking-modal" onClick={(e) => e.stopPropagation()}>
330	              <div className="booking-modal-head">
331	                <h2>{editingId ? 'Edit Booking' : 'Schedule New Delivery'}</h2>
332	                <button className="modal-x" onClick={closeForm} aria-label="Close">✕</button>
333	              </div>
334	
335	              {error && <div className="error-banner" style={{ margin: '0 0 14px' }}>⚠️ {error}</div>}
336	
337	              <form onSubmit={submitBookingForm} className="dark-form">
338	                <div className="form-group">
339	                  <label>Transport Company *</label>
340	                  <input name="transport_company" value={form.transport_company} onChange={onField} placeholder="e.g., NinjaVan" required />
341	                </div>
342	                <div className="form-group">
343	                  <label>Vehicle License Plate *</label>
344	                  <input name="license_plate" value={form.license_plate} onChange={onField} placeholder="e.g., GBG 1234M" required />
345	                </div>
346	                <div className="form-group">
347	                  <label>Driver Name</label>
348	                  <input name="driver_name" value={form.driver_name} onChange={onField} placeholder="e.g., Ahmad" />
349	                </div>
350	                <div className="form-group">
351	                  <label>Driver Phone *</label>
352	                  <input name="driver_phone" type="tel" value={form.driver_phone} onChange={onField} placeholder="+65..." required />
353	                </div>
354	                <div className="form-group">
355	                  <label>Loading Bay *</label>
356	                  <select name="loading_bay" value={form.loading_bay} onChange={onField} required>
357	                    <option value="">Select a bay...</option>
358	                    {BAYS.map(b => <option key={b} value={b}>{b}</option>)}
359	                  </select>
360	                </div>
361	                <div className="form-group">
362	                  <label>Slot Start</label>
363	                  <input name="slot_start" type="datetime-local" value={form.slot_start} onChange={onField} />
364	                </div>
365	                <div className="form-group">
366	                  <label>Slot End</label>
367	                  <input name="slot_end" type="datetime-local" value={form.slot_end} onChange={onField} />
368	                </div>
369	                <div className="form-group">
370	                  <label>Notes</label>
371	                  <input name="notes" value={form.notes} onChange={onField} placeholder="Optional" />
372	                </div>
373	                <div className="booking-modal-actions">
374	                  <button type="button" className="cancel-btn" onClick={closeForm}>Cancel</button>
375	                  <button type="submit" className="submit-booking-btn" disabled={submitting}>
376	                    {submitting ? 'Saving...' : editingId ? 'Save Changes' : 'Create Booking'}
377	                  </button>
378	                </div>
379	              </form>
380	            </div>
381	          </div>
