1	const express = require('express');
2	const router = express.Router();
3	const crypto = require('crypto');
4	const { Op } = require('sequelize');
5	const { Booking, User } = require('../models');
6	const { verifyToken, requireRole } = require('../middlewares/auth');
7	const whatsapp = require('../services/whatsappService');
8	const { verifyGate } = require('../services/gateVerification');
9	
10	const STATUSES = ['Pending', 'Confirmed', 'Arrived', 'Completed', 'Cancelled'];
11	
12	function genRef() {
13	    return `FG-${crypto.randomBytes(3).toString('hex').toUpperCase()}`;
14	}
15	
16	// Resolve which tenant/unit a booking belongs to, based on who is creating it:
17	//   Tenant → their own id; Staff → their managerId (the tenant they work for); FM → optional body.tenantId.
18	// Returns null if it cannot be determined (FM with no tenantId, or Staff with no manager).
19	async function resolveTenantId(user, bodyTenantId) {
20	    if (user.role === 'Tenant') return user.id;
21	    if (user.role === 'Staff') {
22	        const staff = await User.findByPk(user.id, { attributes: ['managerId'] });
23	        return staff?.managerId ?? null;
24	    }
25	    return bodyTenantId || null; // FM
26	}
27	
28	// ---------------------------------------------------------------------------
29	// CREATE — FM, Tenant, or Staff create a loading-bay booking request. (400 on bad input)
30	// Staff may book on behalf of their tenant/unit (booking is linked to their managerId).
31	// ---------------------------------------------------------------------------
32	router.post('/create', verifyToken, requireRole('FM', 'Tenant', 'Staff'), async (req, res) => {
33	    try {
34	        const {
35	            transport_company, license_plate, driver_phone, loading_bay,
36	            driver_name, slot_start, slot_end, notes, tenant_name
37	        } = req.body;
38	
39	        const missing = ['transport_company', 'license_plate', 'driver_phone', 'loading_bay']
40	            .filter(f => !req.body[f] || !String(req.body[f]).trim());
41	        if (missing.length) {
42	            return res.status(400).json({ error: `Missing required field(s): ${missing.join(', ')}.` });
43	        }
44	        if (!/^[+\d][\d\s-]{6,}$/.test(String(driver_phone))) {
45	            return res.status(400).json({ error: 'driver_phone is not a valid phone number.' });
46	        }
47	
48	        // Optional slot-conflict guard (409) when a time window is supplied.
49	        if (slot_start && slot_end) {
50	            if (new Date(slot_end) <= new Date(slot_start)) {
51	                return res.status(400).json({ error: 'slot_end must be after slot_start.' });
52	            }
53	            const clash = await Booking.findOne({
54	                where: {
55	                    loading_bay,
56	                    status: { [Op.ne]: 'Cancelled' },
57	                    slot_start: { [Op.lt]: new Date(slot_end) },
58	                    slot_end: { [Op.gt]: new Date(slot_start) }
59	                }
60	            });
61	            if (clash) {
62	                return res.status(409).json({ error: `${loading_bay} is already booked for that time window.` });
63	            }
64	        }
65	
66	        // Link the booking to a tenant/unit so the right people can see it
67	        // (Tenant → self, Staff → their managerId, FM → optional body.tenantId).
68	        const tenantId = await resolveTenantId(req.user, req.body.tenantId);
69	
70	        const booking = await Booking.create({
71	            booking_ref: genRef(),
72	            transport_company,
73	            license_plate,
74	            driver_phone,
75	            loading_bay,
76	            driver_name: driver_name || null,
77	            slot_start: slot_start || null,
78	            slot_end: slot_end || null,
79	            notes: notes || null,
80	            tenant_name: tenant_name || null,
81	            tenantId,
82	            status: 'Pending'
83	        });
84	
85	        // Confirmation to the driver — non-fatal (must never fail the booking).
86	        let whatsappResult = null;
87	        try {
88	            whatsappResult = await whatsapp.sendBookingCreated(booking);
89	        } catch (waErr) {
90	            console.error('WhatsApp notify failed (non-fatal):', waErr.message);
91	        }
92	
93	        res.status(201).json({ message: 'Booking created.', booking, whatsapp: whatsappResult });
94	    } catch (err) {
95	        console.error('Booking create error:', err);
96	        res.status(500).json({ error: 'Internal server error while creating booking.' });
97	    }
98	});
99	
100	// ---------------------------------------------------------------------------
101	// READ (list) — FM sees all; Tenant sees own unit; Staff sees their unit's bookings.
102	// ---------------------------------------------------------------------------
103	router.get('/', verifyToken, async (req, res) => {
104	    try {
105	        const where = {};
106	        if (req.user.role === 'Tenant') {
107	            where.tenantId = req.user.id;
108	        } else if (req.user.role === 'Staff') {
109	            // Staff only see bookings for the tenant/unit they belong to.
110	            const tenantId = await resolveTenantId(req.user, null);
111	            where.tenantId = tenantId ?? -1; // -1 → matches nothing if no manager set
112	        }
113	        // FM → no filter (all bookings)
114	        const bookings = await Booking.findAll({ where, order: [['createdAt', 'DESC']], limit: 100 });
115	        res.status(200).json(bookings);
116	    } catch (err) {
117	        console.error('Booking list error:', err);
118	        res.status(500).json({ error: 'Could not retrieve bookings.' });
119	    }
120	});
121	
122	// READ (all) — FM-only compat alias (unscoped). Declared BEFORE '/:ref'.
123	router.get('/all', verifyToken, requireRole('FM'), async (req, res) => {
124	    try {
125	        const bookings = await Booking.findAll({ order: [['createdAt', 'DESC']], limit: 100 });
126	        res.status(200).json(bookings);
127	    } catch (err) {
128	        console.error('Booking list error:', err);
129	        res.status(500).json({ error: 'Could not retrieve bookings.' });
130	    }
131	});
132	
133	// ---------------------------------------------------------------------------
134	// UPDATE status — FM only (facility-level: Pending → Confirmed → Arrived → Completed).
135	// Confirmed → WhatsApp slot confirmation. Completed → auto next-in-line alert.
136	// ---------------------------------------------------------------------------
137	router.patch('/:id/status', verifyToken, requireRole('FM'), async (req, res) => {
138	    try {
139	        const { status } = req.body;
140	        if (!STATUSES.includes(status)) {
141	            return res.status(400).json({ error: `status must be one of: ${STATUSES.join(', ')}.` });
142	        }
143	
144	        const booking = await Booking.findByPk(req.params.id);
145	        if (!booking) return res.status(404).json({ error: 'Booking not found.' });
146	
147	        await booking.update({ status });
148	
149	        let whatsappResult = null;
150	        let nextInLine = null;
151	
152	        // All WhatsApp sends are non-fatal — a failure must never fail the status update.
153	        try {
154	            if (status === 'Confirmed') {
155	                whatsappResult = await whatsapp.sendBookingConfirmed(booking);
156	            } else if (status === 'Arrived') {
157	                whatsappResult = await whatsapp.sendBookingArrived(booking);
158	            } else if (status === 'Cancelled') {
159	                whatsappResult = await whatsapp.sendBookingCancelled(booking);
160	            } else if (status === 'Completed') {
161	                // Notify the leaving driver, then alert the next waiting booking for the same bay.
162	                whatsappResult = await whatsapp.sendBookingCompleted(booking);
163	                const next = await Booking.findOne({
164	                    where: { loading_bay: booking.loading_bay, status: { [Op.in]: ['Pending', 'Confirmed'] } },
165	                    order: [['slot_start', 'ASC'], ['createdAt', 'ASC']]
166	                });
167	                if (next) {
168	                    await whatsapp.sendNextInLine(next);
169	                    nextInLine = next.booking_ref;
170	                }
171	            }
172	        } catch (waErr) {
173	            console.error('WhatsApp notify failed (non-fatal):', waErr.message);
174	        }
175	
176	        res.status(200).json({ message: `Booking ${status}.`, booking, whatsapp: whatsappResult, nextInLine });
177	    } catch (err) {
178	        console.error('Booking status error:', err);
179	        res.status(500).json({ error: 'Could not update booking status.' });
180	    }
181	});
182	
183	// ---------------------------------------------------------------------------
184	// EDIT — manual booking update. FM may edit any booking; a Tenant may edit
185	// only their own unit's bookings. Closed bookings cannot be edited.
186	// Editable fields only — status changes stay on /:id/status and /:ref/gate-scan,
187	// and cancellation remains the soft-delete on /:id/cancel.
188	// ---------------------------------------------------------------------------
189	const EDITABLE_FIELDS = [
190	    'transport_company', 'driver_name', 'driver_phone', 'license_plate',
191	    'loading_bay', 'slot_start', 'slot_end', 'notes'
192	];
193	
194	router.patch('/:id', verifyToken, requireRole('FM', 'Tenant'), async (req, res) => {
195	    try {
196	        const booking = await Booking.findByPk(req.params.id);
197	        if (!booking) return res.status(404).json({ error: 'Booking not found.' });
198	
199	        const isFM = req.user.role === 'FM';
200	        const isOwnerTenant = req.user.role === 'Tenant' && booking.tenantId === req.user.id;
201	        if (!isFM && !isOwnerTenant) {
202	            return res.status(403).json({ error: 'You can only edit your own bookings.' });
203	        }
204	        if (['Completed', 'Cancelled'].includes(booking.status)) {
205	            return res.status(409).json({ error: `Cannot edit a ${booking.status} booking.` });
206	        }
207	
208	        // Whitelist — ignore any other fields (status, tenantId, booking_ref…).
209	        const updates = {};
210	        for (const field of EDITABLE_FIELDS) {
211	            if (field in req.body) updates[field] = req.body[field];
212	        }
213	        if (Object.keys(updates).length === 0) {
214	            return res.status(400).json({ error: 'No editable fields supplied.' });
215	        }
216	
217	        if ('driver_phone' in updates && !/^[+\d][\d\s-]{6,}$/.test(String(updates.driver_phone))) {
218	            return res.status(400).json({ error: 'driver_phone is not a valid phone number.' });
219	        }
220	
221	        // Slot-conflict validation on the resulting time window/bay.
222	        const newStart = 'slot_start' in updates ? updates.slot_start : booking.slot_start;
223	        const newEnd = 'slot_end' in updates ? updates.slot_end : booking.slot_end;
224	        const newBay = 'loading_bay' in updates ? updates.loading_bay : booking.loading_bay;
225	        if (newStart && newEnd) {
226	            if (new Date(newEnd) <= new Date(newStart)) {
227	                return res.status(400).json({ error: 'slot_end must be after slot_start.' });
228	            }
229	            const clash = await Booking.findOne({
230	                where: {
231	                    id: { [Op.ne]: booking.id }, // ignore the booking being edited
232	                    loading_bay: newBay,
233	                    status: { [Op.ne]: 'Cancelled' },
234	                    slot_start: { [Op.lt]: new Date(newEnd) },
235	                    slot_end: { [Op.gt]: new Date(newStart) }
236	                }
237	            });
238	            if (clash) {
239	                return res.status(409).json({ error: `${newBay} is already booked for that time window.` });
240	            }
241	        }
242	
243	        await booking.update(updates);
244	        res.status(200).json({ message: 'Booking updated.', booking });
245	    } catch (err) {
246	        console.error('Booking edit error:', err);
247	        res.status(500).json({ error: 'Could not update booking.' });
248	    }
249	});
250	
251	// ---------------------------------------------------------------------------
252	// CANCEL — FM, or the Tenant who owns it. Soft cancel (status='Cancelled').
253	// ---------------------------------------------------------------------------
254	router.patch('/:id/cancel', verifyToken, async (req, res) => {
255	    try {
256	        const booking = await Booking.findByPk(req.params.id);
257	        if (!booking) return res.status(404).json({ error: 'Booking not found.' });
258	
259	        const isFM = req.user.role === 'FM';
260	        const isOwnerTenant = req.user.role === 'Tenant' && booking.tenantId === req.user.id;
261	        if (!isFM && !isOwnerTenant) {
262	            return res.status(403).json({ error: 'You can only cancel your own bookings.' });
263	        }
264	
265	        await booking.update({ status: 'Cancelled' });
266	
267	        // WhatsApp is non-fatal — a notify failure must never fail the cancel.
268	        let whatsappResult = null;
269	        try {
270	            whatsappResult = await whatsapp.sendBookingCancelled(booking);
271	        } catch (waErr) {
272	            console.error('WhatsApp notify failed (non-fatal):', waErr.message);
273	        }
274	
275	        res.status(200).json({ message: 'Booking cancelled.', booking, whatsapp: whatsappResult });
276	    } catch (err) {
277	        console.error('Booking cancel error:', err);
278	        res.status(500).json({ error: 'Could not cancel booking.' });
279	    }
280	});
281	
282	// ---------------------------------------------------------------------------
283	// GATE SCAN — FM only: scan/verify a driver pass by booking_ref at the bay.
284	//   body: { action: 'entry' | 'exit', observedPlate?: string }
285	//   entry: Pending/Confirmed → Arrived (+ WhatsApp arrival)
286	//   exit:  Arrived/Confirmed → Completed (+ WhatsApp completed + next-in-line)
287	// Plate mismatch is flagged (warn) but does not block. WhatsApp is non-fatal.
288	// ---------------------------------------------------------------------------
289	router.patch('/:ref/gate-scan', verifyToken, requireRole('FM'), async (req, res) => {
290	    try {
291	        const { action, observedPlate } = req.body;
292	        if (!['entry', 'exit'].includes(action)) {
293	            return res.status(400).json({ error: "action must be 'entry' or 'exit'." });
294	        }
295	
296	        const booking = await Booking.findOne({ where: { booking_ref: req.params.ref } });
297	        if (!booking) return res.status(404).json({ error: 'Booking not found.' });
298	
299	        // Optional plate verification (warn-only — never blocks the scan).
300	        let plateMatched = null;
301	        if (observedPlate && String(observedPlate).trim()) {
302	            const norm = (s) => String(s || '').toUpperCase().replace(/\s+/g, '');
303	            plateMatched = norm(observedPlate) === norm(booking.license_plate);
304	        }
305	
306	        let whatsappStatus = null;
307	        let nextInLine = null;
308	
309	        if (action === 'entry') {
310	            if (booking.status === 'Cancelled' || booking.status === 'Completed') {
311	                return res.status(409).json({ error: `Cannot mark arrival: booking is ${booking.status}.`, booking, plateMatched });
312	            }
313	            await booking.update({ status: 'Arrived', arrived_at: new Date() });
314	            try {
315	                whatsappStatus = await whatsapp.sendBookingArrived(booking);
316	            } catch (waErr) {
317	                console.error('WhatsApp notify failed (non-fatal):', waErr.message);
318	            }
319	        } else { // exit
320	            if (booking.status === 'Cancelled') {
321	                return res.status(409).json({ error: 'Cannot mark exit: booking is Cancelled.', booking, plateMatched });
322	            }
323	            if (booking.status === 'Completed') {
324	                // Idempotent — already completed, do not re-notify / re-trigger next-in-line.
325	                return res.status(200).json({
326	                    message: 'Booking already completed.', booking, action,
327	                    plateMatched, whatsappStatus: null, nextInLine: null, alreadyCompleted: true
328	                });
329	            }
330	            await booking.update({ status: 'Completed', completed_at: new Date() });
331	            try {
332	                whatsappStatus = await whatsapp.sendBookingCompleted(booking);
333	                const next = await Booking.findOne({
334	                    where: { loading_bay: booking.loading_bay, status: { [Op.in]: ['Pending', 'Confirmed'] } },
335	                    order: [['slot_start', 'ASC'], ['createdAt', 'ASC']]
336	                });
337	                if (next) {
338	                    await whatsapp.sendNextInLine(next);
339	                    nextInLine = next.booking_ref;
340	                }
341	            } catch (waErr) {
342	                console.error('WhatsApp notify failed (non-fatal):', waErr.message);
343	            }
344	        }
345	
346	        return res.status(200).json({
347	            message: `Gate ${action} recorded.`, booking, action, plateMatched, whatsappStatus, nextInLine
348	        });
349	    } catch (err) {
350	        console.error('Gate scan error:', err);
351	        return res.status(500).json({ error: 'Could not process gate scan.' });
352	    }
353	});
354	
355	// ---------------------------------------------------------------------------
356	// GATE VERIFICATION — FM only: dual-mode (automatic QR+plate / manual) loading-bay
357	// gate decision. Delegates ALL rules + audit to the stateless gateVerification
358	// service (booking is re-read from PostgreSQL with a row lock on every call).
359	//   body: { action, bookingRef, observedPlate, verificationMode, plateSource,
360	//           plateConfidence, manualOverride, overrideReason }
361	// Returns a stable decision keyed by reasonCode (200 = decision made; 400 = bad
362	// request; 500 = server/audit failure — access NOT granted). This is additive:
363	// the legacy PATCH /:ref/gate-scan route above is left untouched for compatibility.
364	// ---------------------------------------------------------------------------
365	router.post('/gate-verification', verifyToken, requireRole('FM'), async (req, res) => {
366	    try {
367	        const { http, body } = await verifyGate(req.body || {}, req.user);
