1	// Dual-mode loading-bay gate verification (Proof of Concept).
2	//
3	// Stateless by design: every call re-reads the authoritative booking row from
4	// PostgreSQL (SELECT ... FOR UPDATE inside a transaction when the DB supports it),
5	// so the feature keeps working across Cloud Run restarts / multiple instances and
6	// two simultaneous scans cannot both flip the same booking.
7	//
8	// The same rules serve AUTOMATIC (QR + camera/OCR plate) and MANUAL (FM types the
9	// booking ref + observed plate) modes. Callers get a single, stable decision shape
10	// keyed by `reasonCode` — the frontend never parses English error text.
11	//
12	// This module performs NO Express work; the route is a thin adapter. WhatsApp /
13	// next-in-line notifications reuse the existing whatsappService and run AFTER the
14	// DB transaction commits (never on rollback, never holding a row lock over the
15	// network), preserving the existing driver-notification behaviour.
16	
17	const models = require('../models');
18	const whatsapp = require('./whatsappService');
19	const { writeGateAccessLog } = require('./gateAudit');
20	const { normalizePlate } = require('../utils/plate');
21	
22	const { Op } = require('sequelize');
23	
24	// --- Stable machine reason codes (frontend maps these to copy) ---
25	const REASON = Object.freeze({
26	  VERIFIED: 'VERIFIED',
27	  BOOKING_NOT_FOUND: 'BOOKING_NOT_FOUND',
28	  BOOKING_NOT_CONFIRMED: 'BOOKING_NOT_CONFIRMED',
29	  BOOKING_CANCELLED: 'BOOKING_CANCELLED',
30	  BOOKING_COMPLETED: 'BOOKING_COMPLETED',
31	  ALREADY_ARRIVED: 'ALREADY_ARRIVED',
32	  ALREADY_COMPLETED: 'ALREADY_COMPLETED',
33	  NOT_ARRIVED: 'NOT_ARRIVED',
34	  TOO_EARLY: 'TOO_EARLY',
35	  TOO_LATE: 'TOO_LATE',
36	  PLATE_REQUIRED: 'PLATE_REQUIRED',
37	  PLATE_MISMATCH: 'PLATE_MISMATCH',
38	  OCR_UNREADABLE: 'OCR_UNREADABLE',
39	  CAMERA_UNAVAILABLE: 'CAMERA_UNAVAILABLE',
40	  OVERRIDE_REASON_REQUIRED: 'OVERRIDE_REASON_REQUIRED',
41	  INVALID_ACTION: 'INVALID_ACTION',
42	  AUDIT_FAILED: 'AUDIT_FAILED',
43	});
44	
45	// Failures an authorised FM may deliberately override in MANUAL mode.
46	const REVIEWABLE = new Set([REASON.PLATE_MISMATCH, REASON.OCR_UNREADABLE, REASON.CAMERA_UNAVAILABLE]);
47	
48	const VALID_ACTIONS = new Set(['entry', 'exit']);
49	const VALID_MODES = new Set(['automatic', 'manual']);
50	const VALID_SOURCES = new Set(['ocr', 'simulation', 'manual']);
51	
52	const MESSAGES = {
53	  [REASON.VERIFIED]: 'QR and vehicle plate verified.',
54	  [REASON.BOOKING_NOT_FOUND]: 'No booking matches that reference.',
55	  [REASON.BOOKING_NOT_CONFIRMED]: 'Booking is not Confirmed — it cannot be admitted automatically.',
56	  [REASON.BOOKING_CANCELLED]: 'This booking has been cancelled. Entry is not authorised.',
57	  [REASON.BOOKING_COMPLETED]: 'This booking is already completed.',
58	  [REASON.ALREADY_ARRIVED]: 'Booking has already been marked Arrived.',
59	  [REASON.ALREADY_COMPLETED]: 'Booking has already been completed.',
60	  [REASON.NOT_ARRIVED]: 'Vehicle has no recorded arrival — cannot record exit.',
61	  [REASON.TOO_EARLY]: 'Arrival is earlier than the approved window.',
62	  [REASON.TOO_LATE]: 'Arrival is later than the approved window.',
63	  [REASON.PLATE_REQUIRED]: 'A vehicle plate is required to verify this booking.',
64	  [REASON.PLATE_MISMATCH]: 'Detected plate does not match the approved booking.',
65	  [REASON.OCR_UNREADABLE]: 'The plate could not be read automatically.',
66	  [REASON.CAMERA_UNAVAILABLE]: 'The gate camera was unavailable.',
67	  [REASON.OVERRIDE_REASON_REQUIRED]: 'A manual override requires a reason.',
68	  [REASON.INVALID_ACTION]: "action must be 'entry' or 'exit'.",
69	  [REASON.AUDIT_FAILED]: 'The decision could not be safely recorded — access was not granted.',
70	};
71	
72	// Env-configurable arrival grace (minutes). Read per call so tests/deploys pick up changes.
73	function graceWindow() {
74	  const early = Number(process.env.GATE_EARLY_MINUTES);
75	  const late = Number(process.env.GATE_LATE_MINUTES);
76	  return {
77	    earlyMin: Number.isFinite(early) ? early : 30,
78	    lateMin: Number.isFinite(late) ? late : 60,
79	  };
80	}
81	
82	// Public, FM-safe summary of the booking for the decision payload.
83	function bookingSummary(b) {
84	  if (!b) return null;
85	  return {
86	    booking_ref: b.booking_ref,
87	    transport_company: b.transport_company,
88	    driver_name: b.driver_name,
89	    license_plate: b.license_plate,
90	    loading_bay: b.loading_bay,
91	    slot_start: b.slot_start,
92	    slot_end: b.slot_end,
93	    status: b.status,
94	    arrived_at: b.arrived_at,
95	    completed_at: b.completed_at,
96	  };
97	}
98	
99	// Returns { code, warning? } for the entry arrival-window check.
100	function checkArrivalWindow(booking, now) {
101	  if (!booking.slot_start || !booking.slot_end) {
102	    return { code: null, warning: 'SCHEDULE_UNVERIFIED' }; // allowed, but flagged
103	  }
104	  const { earlyMin, lateMin } = graceWindow();
105	  const start = new Date(booking.slot_start).getTime();
106	  const end = new Date(booking.slot_end).getTime();
107	  if (Number.isNaN(start) || Number.isNaN(end)) {
108	    return { code: null, warning: 'SCHEDULE_UNVERIFIED' };
109	  }
110	  const nowMs = now.getTime();
111	  if (nowMs < start - earlyMin * 60000) return { code: REASON.TOO_EARLY };
112	  if (nowMs > end + lateMin * 60000) return { code: REASON.TOO_LATE };
113	  return { code: null };
114	}
115	
116	// Pure decision core. Given the loaded booking + normalised inputs, decide the
117	// base outcome WITHOUT touching the DB. Returns a plain decision descriptor.
118	function decide(booking, input, now) {
119	  const { action, verificationMode, observedPlate, plateSource } = input;
120	  const expectedPlate = normalizePlate(booking.license_plate);
121	  const observed = normalizePlate(observedPlate);
122	  const hasPlate = observed.length > 0;
123	  const plateMatched = hasPlate ? observed === expectedPlate : null;
124	
125	  const base = {
126	    expectedPlate,
127	    observedPlate: observed || null,
128	    plateMatched,
129	    warning: null,
130	  };
131	
132	  if (action === 'entry') {
133	    if (booking.status === 'Cancelled') return { ...base, grant: false, code: REASON.BOOKING_CANCELLED };
134	    if (booking.status === 'Completed') return { ...base, grant: false, code: REASON.BOOKING_COMPLETED };
135	    if (booking.status === 'Arrived') return { ...base, grant: true, code: REASON.ALREADY_ARRIVED, idempotent: true };
136	    if (booking.status !== 'Confirmed') return { ...base, grant: false, code: REASON.BOOKING_NOT_CONFIRMED };
137	
138	    // Confirmed → time window, then plate.
139	    const window = checkArrivalWindow(booking, now);
140	    if (window.code) return { ...base, grant: false, code: window.code };
141	    base.warning = window.warning || null;
142	
143	    const plate = evaluatePlate({ hasPlate, plateMatched, verificationMode, plateSource });
144	    if (plate) return { ...base, grant: false, code: plate };
145	    return { ...base, grant: true, code: REASON.VERIFIED, transitionTo: 'Arrived' };
146	  }
147	
148	  // action === 'exit'
149	  if (booking.status === 'Cancelled') return { ...base, grant: false, code: REASON.BOOKING_CANCELLED };
150	  if (booking.status === 'Completed') return { ...base, grant: true, code: REASON.ALREADY_COMPLETED, idempotent: true };
151	  if (booking.status !== 'Arrived') return { ...base, grant: false, code: REASON.NOT_ARRIVED };
152	
153	  const plate = evaluatePlate({ hasPlate, plateMatched, verificationMode, plateSource });
154	  if (plate) return { ...base, grant: false, code: plate };
155	  return { ...base, grant: true, code: REASON.VERIFIED, transitionTo: 'Completed' };
156	}
157	
158	// Plate gate shared by entry & exit. Returns a deny reason code, or null to pass.
159	function evaluatePlate({ hasPlate, plateMatched, verificationMode, plateSource }) {
160	  if (!hasPlate) {
161	    // Automatic OCR that came back empty is a reviewable "unreadable"; anything
162	    // else missing a plate is a hard PLATE_REQUIRED.
163	    if (verificationMode === 'automatic' && plateSource === 'ocr') return REASON.OCR_UNREADABLE;
