179	        setOcr({ ...result, simulated: false });
180	        setOcrError('No plate text could be read. Retake the photo, or use manual verification.');
181	      } else {
182	        setOcr({ ...result, simulated: false });
183	      }
184	      setPlateSource('ocr');
185	    } catch (e) {
186	      setOcrError(e.message || 'OCR failed. Please retake the photo.');
187	    } finally {
188	      setOcrBusy(false);
189	    }
190	  };
191	
192	  const captureAndRead = async () => {
193	    if (!plateVideoRef.current) return;
194	    await runOcrOn(plateVideoRef.current);
195	    stopPlateCam();
196	  };
197	
198	  const onUploadImage = async (e) => {
199	    const file = e.target.files?.[0];
200	    e.target.value = ''; // allow re-selecting the same file; nothing is persisted
201	    if (!file) return;
202	    const url = URL.createObjectURL(file);
203	    try {
204	      const img = new Image();
205	      const loaded = new Promise((resolve, reject) => {
206	        img.onload = () => resolve();
207	        img.onerror = () => reject(new Error('Could not read that image.'));
208	      });
209	      img.src = url;
210	      await loaded;
211	      await runOcrOn(img);
212	    } catch (err) {
213	      setOcrError(err.message || 'Could not read that image.');
214	    } finally {
215	      URL.revokeObjectURL(url); // never keep the image around
216	    }
217	  };
218	
219	  const useSimulatedPlate = () => {
220	    const normalized = normalizePlate(simInput);
221	    if (!normalized) { setOcrError('Enter a plate value for the simulated reading.'); return; }
222	    setOcrError('');
223	    setOcr({ raw: simInput.trim(), normalized, confidence: null, simulated: true });
224	    setPlateSource('simulation');
225	  };
226	
227	  const retakePlate = () => {
228	    stopPlateCam();
229	    setOcr(null);
230	    setOcrError('');
231	    setSimInput('');
232	    setPlateSource('ocr');
233	  };
234	
235	  // --- Verification ---
236	  const verify = async (payload) => {
237	    setBusy(true);
238	    setSubmitError('');
239	    setOverrideError('');
240	    try {
241	      const res = await axios.post(`${API_BASE_URL}/api/bookings/gate-verification`, payload, authHeader);
242	      setDecision(res.data);
243	      setLastPayload(payload);
244	      setStep(3);
245	    } catch (err) {
246	      // 400 (bad request) and 500 (audit failure) still carry a decision body.
247	      const data = err.response?.data;
248	      if (data && data.reasonCode) {
249	        setDecision(data);
250	        setLastPayload(payload);
251	        setStep(3);
252	      } else {
253	        setSubmitError('Could not reach the verification service. Please check your connection and try again.');
254	      }
255	    } finally {
256	      setBusy(false);
257	    }
258	  };
259	
260	  const submitAutomatic = () => {
261	    if (!isValidBookingRef(bookingRef)) { setSubmitError('Scan or enter a valid booking reference first.'); return; }
262	    stopAllCameras();
263	    verify({
264	      action,
265	      bookingRef: normalizeBookingRef(bookingRef),
266	      observedPlate: ocr?.normalized || '',
267	      verificationMode: 'automatic',
268	      plateSource,
269	      plateConfidence: ocr?.confidence ?? null,
270	      manualOverride: false,
271	      overrideReason: null,
272	    });
273	  };
274	
275	  const submitManual = () => {
276	    if (!isValidBookingRef(bookingRef)) { setSubmitError('Enter a valid booking reference (e.g. FG-ABC123).'); return; }
277	    verify({
278	      action,
279	      bookingRef: normalizeBookingRef(bookingRef),
280	      observedPlate: normalizePlate(manualPlate),
281	      verificationMode: 'manual',
282	      plateSource: 'manual',
283	      manualOverride: false,
284	      overrideReason: null,
285	    });
286	  };
287	
288	  const authoriseOverride = () => {
289	    if (!overrideReason.trim()) { setOverrideError('A reason is required to authorise a manual override.'); return; }
290	    verify({
291	      ...(lastPayload || {}),
292	      action,
293	      bookingRef: normalizeBookingRef(bookingRef),
294	      verificationMode: 'manual',
295	      plateSource: 'manual',
296	      manualOverride: true,
297	      overrideReason: overrideReason.trim(),
298	    });
299	  };
300	
301	  const reset = () => {
302	    stopAllCameras();
303	    setBookingRef('');
304	    setManualPlate('');
305	    setOcr(null);
306	    setOcrError('');
307	    setQrError('');
308	    setSimInput('');
309	    setPlateSource('ocr');
310	    setDecision(null);
311	    setLastPayload(null);
312	    setOverrideReason('');
313	    setOverrideError('');
314	    setSubmitError('');
315	    setStep(0);
316	  };
317	
318	  const switchMode = (next) => {
319	    if (next === mode) return;
320	    setMode(next);
321	    reset();
322	  };
323	
324	  const decisionGranted = decision?.access === 'GRANTED';
325	  const decisionOverride = Boolean(decision?.overrideUsed);
326	  const reviewable = Boolean(decision && decision.access === 'DENIED' && decision.manualReviewRequired);
327	
328	  return (
329	    <div className="dashboard-layout">
330	      <Sidebar />
331	      <main className="dashboard-main">
332	        <header className="dashboard-header">
333	          <div className="header-titles">
334	            <h1>Loading Bay Gate Verification</h1>
335	            <p>Dual-mode QR &amp; vehicle-plate check for the loading-bay barrier (Proof of Concept).</p>
336	          </div>
337	          <div className="header-actions">
338	            <button type="button" className="edit-btn" onClick={() => navigate('/logistics')}>← Back to Logistics</button>
339	          </div>
340	        </header>
341	
342	        {/* Entry / Exit selector */}
343	        <div className="gate-action-selector" role="group" aria-label="Gate action">
344	          <button
345	            type="button"
346	            className={`gate-seg ${action === 'entry' ? 'active' : ''}`}
347	            aria-pressed={action === 'entry'}
348	            onClick={() => setAction('entry')}
349	          >⇥ Entry (Arrival)</button>
350	          <button
351	            type="button"
352	            className={`gate-seg ${action === 'exit' ? 'active' : ''}`}
353	            aria-pressed={action === 'exit'}
354	            onClick={() => setAction('exit')}
355	          >⇤ Exit (Departure)</button>
356	        </div>
357	
358	        {/* Mode tabs */}
359	        <div className="gate-tabs" role="tablist" aria-label="Verification mode">
360	          <button
361	            type="button" role="tab" aria-selected={mode === 'automatic'}
362	            className={`gate-tab ${mode === 'automatic' ? 'active' : ''}`}
363	            onClick={() => switchMode('automatic')}
364	          >Automatic Verification</button>
365	          <button
366	            type="button" role="tab" aria-selected={mode === 'manual'}
367	            className={`gate-tab ${mode === 'manual' ? 'active' : ''}`}
368	            onClick={() => switchMode('manual')}
369	          >Manual Verification</button>
370	        </div>
371	
372	        {submitError && <div className="error-banner" style={{ margin: '12px 0' }}>⚠️ {submitError}</div>}
373	
374	        <div className="gate-grid">
375	          {/* LEFT: capture / input workflow */}
376	          <section className="gate-panel">
377	            {mode === 'automatic' ? (
378	              <>
379	                {/* Step indicator */}
380	                <ol className="gate-steps" aria-label="Verification progress">
381	                  {AUTO_STEPS.map((label, i) => (
382	                    <li key={label} className={`gate-step ${i === step ? 'current' : ''} ${i < step ? 'done' : ''}`}>
383	                      <span className="gate-step-num">{i < step ? '✓' : i + 1}</span>
384	                      <span className="gate-step-label">{label}</span>
385	                    </li>
386	                  ))}
387	                </ol>
388	
389	                {/* Step 1: Scan QR */}
390	                <div className="gate-block">
391	                  <h3>1 · Scan Driver QR</h3>
392	                  <div className="gate-video-wrap">
393	                    <video ref={qrVideoRef} className="gate-video" muted playsInline aria-label="QR scanner preview" />
394	                    {!scanning && <div className="gate-video-idle">Camera is off</div>}
395	                  </div>
396	                  {qrError && <div className="gate-inline-error" role="alert">⚠️ {qrError}</div>}
397	                  <div className="gate-btn-row">
398	                    {!scanning ? (
399	                      <button type="button" className="new-booking-btn" onClick={startQr}>Start QR Scanner</button>
400	                    ) : (
401	                      <button type="button" className="cancel-btn" onClick={stopQr}>Stop Scanner</button>
402	                    )}
403	                  </div>
404	                  <div className="gate-fallback">
405	                    <label htmlFor="gate-ref">Or enter booking reference (manual fallback)</label>
406	                    <div className="gate-btn-row">
407	                      <input
408	                        id="gate-ref"
409	                        aria-label="Booking reference"
410	                        placeholder="FG-ABC123"
411	                        value={bookingRef}
412	                        onChange={(e) => setBookingRef(e.target.value)}
413	                      />
414	                      <button type="button" className="edit-btn" onClick={useTypedRef}>Use reference</button>
415	                    </div>
416	                  </div>
417	                  {bookingRef && isValidBookingRef(bookingRef) && (
418	                    <p className="gate-ok">Booking reference set: <strong>{normalizeBookingRef(bookingRef)}</strong></p>
419	                  )}
420	                </div>
421	
422	                {/* Step 2: PoC Plate OCR */}
423	                <div className="gate-block">
424	                  <h3>2 · PoC Plate OCR</h3>
425	                  <p className="gate-note">
426	                    <strong>PoC Plate OCR.</strong> Recognition accuracy may vary with lighting, glare,
427	                    camera angle and plate condition. Manual verification is available.
428	                  </p>
429	                  <div className="gate-video-wrap">
430	                    <video ref={plateVideoRef} className="gate-video" muted playsInline aria-label="Plate camera preview" />
431	                    {!plateCamActive && <div className="gate-video-idle">Camera is off</div>}
432	                  </div>
433	                  {ocrError && <div className="gate-inline-error" role="alert">⚠️ {ocrError}</div>}
434	                  <div className="gate-btn-row">
435	                    {!plateCamActive ? (
436	                      <button type="button" className="edit-btn" onClick={startPlateCam}>Start Camera</button>
437	                    ) : (
438	                      <button type="button" className="new-booking-btn" onClick={captureAndRead} disabled={ocrBusy}>
439	                        {ocrBusy ? 'Reading…' : 'Capture & Read Plate'}
440	                      </button>
441	                    )}
442	                    <label className="gate-upload edit-btn">
443	                      Upload Plate Image
444	                      <input type="file" accept="image/*" aria-label="Upload plate image" onChange={onUploadImage} hidden />
445	                    </label>
446	                    {ocr && <button type="button" className="cancel-btn" onClick={retakePlate}>Retake</button>}
447	                  </div>
448	
449	                  {/* Clearly-labelled simulated provider for controlled demos */}
450	                  <details className="gate-sim">
451	                    <summary>Simulated LPR (demo)</summary>
452	                    <p className="gate-note">
453	                      <strong>Simulated LPR — PoC demonstration.</strong> This is not real AI recognition;
454	                      it stands in for the camera during controlled demos.
455	                    </p>
456	                    <div className="gate-btn-row">
457	                      <input
458	                        aria-label="Simulated plate"
459	                        placeholder="e.g. GBG 1234M"
460	                        value={simInput}
461	                        onChange={(e) => setSimInput(e.target.value)}
462	                      />
463	                      <button type="button" className="edit-btn" onClick={useSimulatedPlate}>Use simulated plate</button>
464	                    </div>
465	                  </details>
466	
467	                  {ocr && (
468	                    <div className="gate-ocr-result" aria-label="OCR result">
469	                      {ocr.simulated && <span className="gate-badge sim">Simulated LPR — PoC demonstration</span>}
470	                      <div className="gate-ocr-row"><span>Raw OCR text</span><code>{ocr.raw || '(none)'}</code></div>
471	                      <div className="gate-ocr-row"><span>Normalised plate</span><strong>{ocr.normalized || '(none)'}</strong></div>
472	                      <div className="gate-ocr-row">
473	                        <span>OCR confidence</span>
474	                        <span>{ocr.confidence == null ? '—' : `${ocr.confidence}%`}</span>
475	                      </div>
476	                    </div>
477	                  )}
478	                </div>
479	
480	                {/* Step 3: Verify */}
481	                <div className="gate-block">
482	                  <h3>3 · Verify Access</h3>
483	                  <button type="button" className="new-booking-btn gate-verify-btn" onClick={submitAutomatic} disabled={busy}>
484	                    {busy ? 'Verifying…' : `Verify ${action === 'entry' ? 'Entry' : 'Exit'}`}
485	                  </button>
486	                </div>
487	              </>
488	            ) : (
489	              /* MANUAL TAB */
490	              <div className="gate-block">
491	                <h3>Manual Verification</h3>
492	                <p className="gate-note">
493	                  Manually confirm the booking reference and the plate you observe on the vehicle.
494	                  A mismatch is denied unless you perform an audited manual override.
495	                </p>
496	                <div className="form-group">
497	                  <label htmlFor="gate-ref-m">Booking Reference *</label>
498	                  <input
499	                    id="gate-ref-m"
500	                    aria-label="Booking reference"
501	                    placeholder="FG-ABC123"
502	                    value={bookingRef}
503	                    onChange={(e) => setBookingRef(e.target.value)}
504	                  />
505	                </div>
506	                <div className="form-group">
507	                  <label htmlFor="gate-plate-m">Observed Vehicle Plate *</label>
508	                  <input
509	                    id="gate-plate-m"
510	                    aria-label="Observed vehicle plate"
511	                    placeholder="e.g. GBG 1234M"
512	                    value={manualPlate}
513	                    onChange={(e) => setManualPlate(e.target.value)}
514	                  />
515	                </div>
516	                <button type="button" className="new-booking-btn gate-verify-btn" onClick={submitManual} disabled={busy}>
517	                  {busy ? 'Verifying…' : `Verify ${action === 'entry' ? 'Entry' : 'Exit'}`}
518	                </button>
519	              </div>
520	            )}
521	          </section>
522	
523	          {/* RIGHT: decision */}
524	          <section className="gate-panel gate-decision-panel">
525	            <h3>{AUTO_STEPS[3]}</h3>
526	            {!decision ? (
527	              <div className="gate-decision-empty">
528	                <p>No decision yet. Complete the steps and press <strong>Verify</strong>.</p>
529	              </div>
530	            ) : (
531	              <div className={`gate-decision ${decisionGranted ? 'granted' : 'denied'}`} role="status" aria-live="polite">
532	                <div className="gate-decision-head">
533	                  <span className="gate-decision-icon" aria-hidden="true">{decisionGranted ? '✓' : '✕'}</span>
534	                  <span className="gate-decision-title">
535	                    {decisionGranted
536	                      ? (decisionOverride ? 'ACCESS GRANTED — MANUAL OVERRIDE' : 'ACCESS GRANTED')
537	                      : 'ACCESS DENIED'}
538	                  </span>
539	                </div>
540	
541	                <p className="gate-decision-msg">{REASON_TEXT[decision.reasonCode] || decision.message}</p>
542	
543	                {decisionGranted ? (
544	                  <div className="gate-barrier" aria-label="Barrier simulation">
545	                    <div className="gate-barrier-track"><div className="gate-barrier-arm open" /></div>
546	                    <p className="gate-sim-note">
547	                      {decisionOverride
548	                        ? <>Approved by Facilities Manager. Reason: <em>{lastPayload?.overrideReason}</em></>
549	                        : <>Proceed to {decision.booking?.loading_bay || 'the assigned bay'}.</>}
550	                    </p>
551	                    <p className="gate-sim-note muted">Barrier opening simulated — no physical barrier is connected.</p>
552	                  </div>
553	                ) : (
554	                  <div className="gate-barrier denied" aria-label="Barrier simulation">
555	                    <div className="gate-barrier-track"><div className="gate-barrier-arm closed" /></div>
556	                    <p className="gate-sim-note">Barrier remains closed.{reviewable ? ' Manual verification required.' : ''}</p>
557	                  </div>
558	                )}
559	
560	                {decision.warning === 'SCHEDULE_UNVERIFIED' && (
561	                  <p className="gate-inline-error" role="alert">⚠️ Schedule validation was unavailable (no slot on this booking).</p>
562	                )}
563	
564	                {/* Plate comparison */}
565	                <div className="gate-compare">
566	                  <div><span>Expected plate</span><strong>{decision.expectedPlate || '—'}</strong></div>
567	                  <div><span>Detected plate</span><strong>{decision.observedPlate || '—'}</strong></div>
568	                  <div>
569	                    <span>Plate check</span>
570	                    <strong className={decision.plateMatched ? 'match' : 'mismatch'}>
571	                      {decision.plateMatched == null ? '—' : decision.plateMatched ? '✓ Match' : '✕ Mismatch'}
572	                    </strong>
573	                  </div>
574	                </div>
575	
576	                {lastPayload?.plateSource === 'simulation' && (
577	                  <span className="gate-badge sim">Simulated LPR — PoC demonstration</span>
578	                )}
579	
580	                {/* Booking summary */}
581	                {decision.booking && (
582	                  <div className="gate-summary">
583	                    <div><span>Reference</span><strong>{decision.booking.booking_ref}</strong></div>
584	                    <div><span>Company</span><strong>{decision.booking.transport_company || '—'}</strong></div>
585	                    <div><span>Driver</span><strong>{decision.booking.driver_name || '—'}</strong></div>
586	                    <div><span>Bay</span><strong>{decision.booking.loading_bay || '—'}</strong></div>
587	                    <div><span>Slot</span><strong>{fmtSlot(decision.booking.slot_start)}</strong></div>
588	                    <div><span>Status</span><strong>{decision.booking.status}</strong></div>
589	                  </div>
590	                )}
591	
592	                {/* Override path for reviewable denials */}
593	                {reviewable && (
594	                  <div className="gate-override">
595	                    <h4>Authorised manual override</h4>
596	                    <p className="gate-note">Overriding a plate/OCR failure is recorded against your account.</p>
597	                    <textarea
598	                      aria-label="Override reason"
599	                      placeholder="Reason for override (required)"
600	                      value={overrideReason}
601	                      onChange={(e) => setOverrideReason(e.target.value)}
602	                      rows={2}
603	                    />
604	                    {overrideError && <div className="gate-inline-error" role="alert">⚠️ {overrideError}</div>}
605	                    <button type="button" className="new-booking-btn" onClick={authoriseOverride} disabled={busy}>
606	                      {busy ? 'Working…' : 'Authorise Manual Override'}
607	                    </button>
608	                  </div>
609	                )}
610	
611	                <button type="button" className="edit-btn gate-reset-btn" onClick={reset}>New Scan</button>
612	              </div>
613	            )}
614	          </section>
615	        </div>
616	      </main>
617	    </div>
618	  );
619	};
620	
621	export default GateVerification;
