2	import { useNavigate } from 'react-router-dom';
3	import axios from 'axios';
4	import Sidebar from '../components/Sidebar';
5	import '../css/Dashboard.css';
6	import '../css/Management.css';
7	import '../css/Booking.css';
8	import { API_BASE_URL } from '../constants/api';
9	import {
10	  singaporeLocalInputToIso,
11	  isoToSingaporeLocalInput,
12	  formatSingaporeBookingDateTime,
13	  singaporeDateKey,
14	} from '../constants/datetime';
15	
16	const BAYS = ['Bay A', 'Bay B'];
17	const STATUSES = ['Pending', 'Confirmed', 'Arrived', 'Completed', 'Cancelled'];
18	const STATUS_FLOW = { Pending: 'Confirmed', Confirmed: 'Arrived', Arrived: 'Completed' };
19	const CLOSED = ['Completed', 'Cancelled'];
20	
21	const emptyForm = {
22	  transport_company: '', license_plate: '', driver_phone: '',
23	  driver_name: '', loading_bay: '', slot_start: '', slot_end: '', notes: ''
24	};
25	
26	const TenantLogistics = () => {
27	  const navigate = useNavigate();
28	  const [bookings, setBookings] = useState([]);
29	  const [loading, setLoading] = useState(true);
30	  const [error, setError] = useState('');
31	  const [notice, setNotice] = useState('');
32	  const [form, setForm] = useState(emptyForm);
33	  const [submitting, setSubmitting] = useState(false);
34	
35	  // Booking form is hidden by default and opens in a modal (keeps the list roomy).
36	  const [isFormOpen, setIsFormOpen] = useState(false);
37	  // Manual UPDATE evidence: when set, the modal edits this booking via PATCH /api/bookings/:id.
38	  const [editingId, setEditingId] = useState(null);
39	  // Frontend-only filtering (backend has no booking filter endpoint).
40	  const [searchText, setSearchText] = useState('');
41	  const [filterStatus, setFilterStatus] = useState('All');
42	  const [filterBay, setFilterBay] = useState('All');
43	  const [filterDate, setFilterDate] = useState(''); // YYYY-MM-DD; empty = all dates
44	
45	  const token = localStorage.getItem('accessToken');
46	  const role = localStorage.getItem('userRole');
47	  const authHeader = { headers: { Authorization: `Bearer ${token}` } };
48	
49	  const canManage = role === 'FM';                                    // status updates (facility-level) — FM only
50	  const canGateScan = role === 'FM';                                  // gate entry/exit — FM only
51	  const canCreate = role === 'FM' || role === 'Tenant' || role === 'Staff'; // create bookings (Staff books for their unit)
52	
53	  const fetchBookings = async () => {
54	    setLoading(true);
55	    setError('');
56	    try {
57	      const res = await axios.get(`${API_BASE_URL}/api/bookings/`, authHeader);
58	      setBookings(Array.isArray(res.data) ? res.data : []);
59	    } catch (err) {
60	      console.error('Failed to fetch bookings:', err);
61	      setError('Could not load bookings. Please try again.');
62	      setBookings([]);
63	    } finally {
64	      setLoading(false);
65	    }
66	  };
