74	  }, [notice]);
75	
76	  const onField = (e) => setForm(prev => ({ ...prev, [e.target.name]: e.target.value }));
77	
78	  const openForm = () => { setError(''); setForm(emptyForm); setEditingId(null); setIsFormOpen(true); };
79	  const closeForm = () => { setIsFormOpen(false); setEditingId(null); };
